<?php use App\Models\Ticket; foreach($listOrder as $column): switch($column):case 'type': ?><td data-column="type" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><span class="ticket-mark-label"><?= work_mark('type',$t['type'],(int)$t['project_id']) ?><span data-type-label hidden><?= e(App\Models\Workflow::label('type',(int)$t['project_id'],$t['type'])) ?></span></span></td><?php break; case 'key': ?><td data-column="key" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><a class="ticket-key" href="<?= e(ticket_url((int)$t['id'])) ?>"><?= e($t['key']) ?></a></td><?php break; case 'title': ?><td class="title-cell" data-column="title" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><div class="ticket-title-line"><?php if(!empty($filters['hierarchy'])&&!empty($childrenByParent[$t['id']])): ?><button class="tiny-button" data-toggle-children="<?= (int)$t['id'] ?>" aria-expanded="true" aria-label="Afficher ou masquer les tickets enfants">⌄</button><?php endif; ?><?php if(!empty($filters['hierarchy'])&&$t['parent_id']): ?><span class="hierarchy-indent">↳</span><?php endif; ?><a class="ticket-summary-link" title="<?= e($t['title']) ?>" href="<?= e(ticket_url((int)$t['id'])) ?>"><?= e($t['title']) ?></a><?= blocked_badge((bool)$t['flagged']) ?><?php if(!empty($t['has_merge_conflict'])): ?><span class="merge-conflict-badge" title="Conflit de fusion signalé dans une pull request"><?= icon('alert') ?><span>Conflit Git</span></span><?php endif; ?><button class="inline-edit" data-edit-field="title" data-value="<?= e($t['title']) ?>" aria-label="Modifier le résumé">✎</button></div></td><?php break; case 'progress_percent': ?>
<td data-column="progress_percent" <?= in_array($column,$listColumns,true)?'':'hidden' ?>>
  <div class="ticket-progress">
    <div class="ticket-progress-meter" data-progress-bar>
      <progress value="<?= (int)$t['progress_percent'] ?>" max="100" aria-label="<?= e('Avancement de '.$t['key']) ?>" data-progress-meter><?= (int)$t['progress_percent'] ?> %</progress>
      <span data-progress-percent aria-hidden="true"><?= (int)$t['progress_percent'] ?> %</span>
    </div>
    <small data-progress-estimate<?= $t['remaining_hours']===null?'':' title="'.e('Reste estimé : '.App\Core\View::hours($t['remaining_hours'])).'"' ?>><?= $t['estimated_hours']===null?'Estimation manquante':'Estimé : '.e(App\Core\View::hours($t['estimated_hours'])) ?></small>
  </div>
</td><?php break; case 'git': ?>
<td data-column="git" <?= in_array($column,$listColumns,true)?'':'hidden' ?>>
  <?php require ROOT.'/app/Views/partials/list-ticket-git.php'; ?>
</td><?php break; case 'development': ?><td data-column="development" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><?php $deploymentBadge=$deploymentBadges[$t['id']]??null;require ROOT.'/app/Views/partials/deployment-badge.php'; ?></td><?php break; case 'assignee': ?><td data-column="assignee" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><div class="cell-assignee"><span class="assignee-avatar-display" aria-hidden="true"><?= avatar($t['assignee_name'],'small',$t['assignee_id']?(int)$t['assignee_id']:null) ?></span><select class="cell-select" data-quick-field="assignee_id" aria-label="Personne assignée pour <?= e($t['key']) ?>"><option value="">Non assigné</option><?php foreach($members as $m): ?><option value="<?= (int)$m['id'] ?>" <?= $t['assignee_id']===$m['id']?'selected':'' ?>><?= e($m['name']) ?></option><?php endforeach; ?></select></div></td><?php break; case 'team': ?><td data-column="team" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><?= e($t['team_name']??'Sans équipe') ?></td><?php break; case 'priority': ?><td data-column="priority" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><div class="cell-priority"><?= work_mark('priority',$t['priority']) ?><select class="cell-select" data-quick-field="priority" aria-label="Priorité pour <?= e($t['key']) ?>"><?php foreach(Ticket::PRIORITIES as $v=>$l): ?><option value="<?= e($v) ?>" <?= $t['priority']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></div></td><?php break; case 'status': ?><td data-column="status" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><select class="status-select workflow-status" data-status-color="<?= e($t['status_color']) ?>" data-quick-field="status" title="<?= e($t['status_label']) ?>" aria-label="État pour <?= e($t['key']) ?>"><?php foreach($t['status_options'] as $v=>$l): ?><option value="<?= e($v) ?>" <?= $t['status']===$v?'selected':'' ?>><?= e($l) ?></option><?php endforeach; ?></select></td><?php break; case 'start': case 'due': $ticketDateField=$column==='start'?'start_date':'due_date'; ?><td data-column="<?= e($column) ?>" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><?php if($t[$ticketDateField]): ?><time datetime="<?= e($t[$ticketDateField]) ?>"><?= e(date('d/m/Y',strtotime($t[$ticketDateField]))) ?></time><?php else: ?><span class="muted">—</span><?php endif; ?></td><?php break; case 'estimated_hours': ?><td data-column="estimated_hours" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><span class="ticket-estimate-value"><?= $t['estimated_hours']===null?'—':e(App\Core\View::hours($t['estimated_hours'])) ?></span></td><?php break; case 'labels': ?><td data-column="labels" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><?php foreach($t['labels_array'] as $label): ?><span class="label-tag"><?= e($label) ?></span><?php endforeach; ?></td><?php break; case 'created': ?><td data-column="created" <?= in_array($column,$listColumns,true)?'':'hidden' ?> class="muted"><?= e(substr($t['created_at'],0,10)) ?></td><?php break; case 'updated': ?><td data-column="updated" <?= in_array($column,$listColumns,true)?'':'hidden' ?>><time data-ticket-modified datetime="<?= e(str_replace(' ','T',$t['updated_at']).'Z') ?>" title="<?= e($t['updated_at'].' UTC') ?>"><?= e(date('d/m/Y',strtotime($t['updated_at'].' UTC'))) ?></time></td><?php break; endswitch; endforeach; ?>